#!/usr/bin/env python3
"""Generates src/ZBCaseFold.c's table (src/ZBCaseFoldTable.inc) from Unicode's
full case folding (CaseFolding.txt statuses C, S and F), as exposed by Python's
str.casefold() (Unicode data of the interpreter running this script).

Usage: python3 tools/gen_casefold.py > src/ZBCaseFoldTable.inc
"""
import sys
import unicodedata

print("/* Generated by tools/gen_casefold.py from Unicode %s full case folding"
      " (CaseFolding.txt C+S+F). Do not edit. */" % unicodedata.unidata_version)
n = 0
for cp in range(0x110000):
    if 0xD800 <= cp <= 0xDFFF:
        continue
    folded = chr(cp).casefold()
    if folded == chr(cp):
        continue
    cps = [ord(c) for c in folded]
    cps += [0] * (3 - len(cps))
    print("    {0x%05X, {0x%04X, 0x%04X, 0x%04X}}," % (cp, *cps))
    n += 1
sys.stderr.write("%d entries\n" % n)
